    if (hayDialogo() || panelId) return;
    const ahora = performance.now();
    if (ahora < cuernoListoEn) { avisar(`El cuerno se está recuperando: ${Math.ceil((cuernoListoEn - ahora) / 1000)} s.`); return; }
    cuernoHasta = ahora + CUERNO_DURA; cuernoListoEn = ahora + CUERNO_RECARGA;
    moral = Math.min(200, moral + 100); moralMostrada = -1;
