      try { if (audioUltra) audioUltra.pause(); } catch (e) { /* nada */ }
      rayoPListoEn = performance.now() + COOLDOWN_RAYO_P;
      avisar(`¡Rayo completo! ${pf} perfects seguidos. Recarga de 3 minutos.`);
