    g.clearRect(0, 0, W2, H2);
    g.fillStyle = "rgba(20,4,6,.96)"; rrPath(g, 0, 0, W2, H2, 14); g.fill();
    g.strokeStyle = "#ff3b3b"; g.lineWidth = 2; rrPath(g, 1, 1, W2 - 2, H2 - 2, 13); g.stroke();
