      G.fillStyle = "#fef08a"; for (let i = 0; i < 26; i++) { const x = (i * 37 + Math.floor(ahora / 140) * (i % 3 + 1)) % 160, y = 44 + (i * 13) % 54; G.fillRect(x, y, 3, 1); }
      G.fillStyle = "#78350f"; G.fillRect(0, 70, 34, 6); G.fillStyle = "#92400e"; for (let x = 0; x < 34; x += 6) G.fillRect(x, 70, 5, 6);   // muelle
