        if (etapa !== "resultado" && etapa !== "fallo") { G.fillStyle = "#ef4444"; G.fillRect(Math.round(bx) - 1, Math.round(by) - 2, 3, 2); G.fillStyle = "#fff"; G.fillRect(Math.round(bx) - 1, Math.round(by), 3, 2); }
        if (etapa === "pico" || etapa === "pelea") { G.fillStyle = "rgba(255,255,255,.6)"; const r = (ahora / 8) % 10; G.fillRect(bx - r, by + 2, r * 2, 1); }
