    if (conTorta()) { c.font = "16px system-ui"; c.textAlign = "center"; c.textBaseline = "middle"; c.fillText("🥪", px + 12, py - (sentado ? 22 : 28)); }
    c.font = "600 11px system-ui, sans-serif"; c.textAlign = "center"; c.textBaseline = "middle";
    const w = c.measureText("Don Carlos").width + 12, ly = sentado ? py - 58 : py - 66;
