  // "casa" (pasillo del primer piso) · "sigue" (te acompaña) · "arena" (al final, en el Coliseo con Don Carlos)
  const mayteFase = () => mayteHecha() || mayteListaParaEntregar() ? "arena" : mayteActiva() ? "sigue" : "casa";
  const AP_MAYTE = { nombre: "Mayte", piel: PIEL[2], pelo: "#3b2416", peinado: "largo", ropa: "#ec4899", pantalon: "#1f2937", accesorio: "ninguno", gordo: 1.8 };
  const MAYTE_CASA = PL(12.4, 27.6), MAYTE_ARENA = [COL_CX - 2.2, PF.y1 - 4.2], CARLOS_ARENA = [COL_CX + 2.2, PF.y1 - 4.2];
