    actualizarRayoUltra(dt);
    actualizarMarshmello(dt);
    actualizarMayte(dt);
    actualizarTele();
    actualizarTeleGigante();
    actualizarBalas(dt);
    actualizarEnemigos(dt);
    actualizarColiseo(dt);
    // Cámara
