    if (cam.px === undefined) { cam.px = px; cam.py = py; }
    const k = 1 - Math.exp(-dt * 7); cam.px += (px - cam.px) * k; cam.py += (py - cam.py) * k;
    // Pequeña sacudida de cámara mientras dura el rayo definitivo (tecla P)
